'use strict';
(()=>{
const KEY='grp_antbro_bureau_pro_v5_20261107';
const PREVIOUS_KEY='grp_antbro_bureau_pro_v4_20261107';
const MEDIA_DEFAULT={playlistUrl:'',liveUrl:'',liveTitle:'ANTBRO LIVE',onAir:'archives'};
const GROUPS=[
 {id:'grp-intl',name:'GRP International',abbr:'GRP',kind:'Organisation',mission:'Communications générales et informations officielles selon les règles GRP.',lead:'',link:'',rules:'Publier les communications officielles dans le bon espace.'},
 {id:'grp-knowledge',name:'GRP Knowledge',abbr:'K',kind:'Apprentissage',mission:'Partage de ressources et développement des connaissances.',lead:'',link:'',rules:'Privilégier les ressources utiles, vérifiables et bien classées.'},
 {id:'grp-qb',name:'GRP QB',abbr:'QB',kind:'Communauté',mission:'Espace spécialisé dont la mission définitive doit être confirmée par GRP.',lead:'',link:'',rules:'Respecter le mandat établi par les responsables GRP.'},
 {id:'grp-fans',name:'GRP Fans',abbr:'FAN',kind:'Communauté',mission:'Espace pour les membres et les fans selon les règles de GRP.',lead:'',link:'',rules:'Respect des membres et des limites de participation.'},
 {id:'grp-jrp',name:'JRP',abbr:'JRP',kind:'Communauté',mission:'Espace à structurer et à préciser avec son responsable.',lead:'',link:'',rules:'Respecter les règles de l’espace.'},
 {id:'grp-live',name:'Antbro Live',abbr:'LIVE',kind:'Émission',mission:'Entrevues, présentation d’artistes et rendez-vous de diffusion.',lead:'Antbro',link:'',rules:'Annonces d’émissions et communications vérifiées.'}
];
const MILESTONES=['Découverte','Contact initial','Profil complété','Profil Hedliner publié','Entrevue préparée','Entrevue réalisée','Promotion publiée','Booking confirmé'];
const PAGES=[['dashboard','Tableau de bord','⌂'],['djs','DJ & artistes','♫'],['groups','Groupes GRP','♣'],['interviews','Entrevues LIVE','▣'],['tv','ANTBRO TV · Moniteurs','▶'],['booking','Booking','▤'],['announcements','Babillard','✦'],['activities','Journal & suivis','☑'],['mail','Courriels & dossiers','✉'],['reports','Bilans','▥'],['settings','Réglages','⚙']];
const START=()=>({version:5,media:{...MEDIA_DEFAULT},djs:[],groups:structuredClone(GROUPS),interviews:[],bookings:[],posts:[],activities:[],tasks:[],mailHistory:[],settings:{to:'',cc:'',signature:'ANTBRO | GRP INTERNATIONAL',language:'fr'},updated:new Date().toISOString()});
function safe(s){return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function urlSafe(s){try{let v=new URL(String(s));return /^https?:$/.test(v.protocol)?v.href:'';}catch{return '';}}
function uid(){return (globalThis.crypto?.randomUUID?.()||('grp-'+Date.now()+'-'+Math.random().toString(36).slice(2)));}
function now(){return new Date().toISOString()}
function day(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function prettyDate(v){if(!v)return 'Date à fixer';try{let d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(String(v))?String(v)+'T12:00:00':v);return isNaN(d)?String(v):d.toLocaleDateString('fr-CA',{year:'numeric',month:'short',day:'numeric'})}catch{return v}}
function migrateV3(x){if(!x||x.v!==2||!Array.isArray(x.djs))return null;
 let out=START(),idx={'intl':'grp-intl','knowledge':'grp-knowledge','qb':'grp-qb','fans':'grp-fans','jrp':'grp-jrp','antbro':'grp-live'};
 for(const old of x.groups||[]){let g=out.groups.find(z=>z.id===idx[old.id]);if(g){g.name=old.name||g.name;g.mission=old.scope||g.mission;g.kind=old.category||g.kind;g.lead=old.lead||'';g.rules=old.rules||g.rules;g.link=old.url||''}}
 const stepMap={profile:2,hedliner:3,representation:4,show:5,promo:6,pitch:7,date:7,review:7};
 out.djs=x.djs.filter(z=>z&&z.name&&!z.demo&&!String(z.id).startsWith('demo-')).map(z=>({id:z.id||uid(),name:z.name,genre:z.style||'',city:z.region||'',status:'En développement',tiktok:urlSafe(z.handle)||'',hedliner:z.hedliner||'',photo:'',notes:z.note||'',steps:[...new Set((z.done||[]).map(k=>stepMap[k]).filter(k=>Number.isInteger(k)))].sort()}));
 out.posts=(x.posts||[]).filter(z=>z&&!z.demo&&!String(z.id).startsWith('seed-')).map(z=>({id:z.id||uid(),title:z.title||'',body:z.body||'',target:out.groups.find(g=>g.id===idx[z.target])?.name||'Tous les groupes',status:z.status==='en attente'?'À faire valider':'Brouillon',date:z.date||day()}));
 out.bookings=(x.opps||[]).filter(z=>z&&!z.demo&&z.title).map(z=>({id:z.id||uid(),title:z.title,djId:z.dj||'',place:z.owner||'',status:z.stage==='confirmée'?'Confirmée':'Prospection',date:z.due||'',fee:'',notes:z.notes||''}));
 return out}
let data;try{
 data=JSON.parse(localStorage.getItem(KEY)||'null');
 if(!data||data.version!==5||!Array.isArray(data.djs)||!Array.isArray(data.groups)){
  const previous=JSON.parse(localStorage.getItem(PREVIOUS_KEY)||'null');
  if(previous&&previous.version===4&&Array.isArray(previous.djs)&&Array.isArray(previous.groups))data={...previous,version:5,media:{...MEDIA_DEFAULT,...(previous.media||{})}};
  else {const old=JSON.parse(localStorage.getItem('grp_community_growth_pro_v2_20261107')||'null');data=migrateV3(old)||START();data.version=5;}
 }
}catch{data=START()}
for(const k of ['djs','groups','interviews','bookings','posts','activities','tasks','mailHistory'])if(!Array.isArray(data[k]))data[k]=[];
data.settings={...START().settings,...(data.settings||{})};
data.media={...MEDIA_DEFAULT,...(data.media||{})};
let page='dashboard',search='',mailDraft=null;
const $=id=>document.getElementById(id);
function persist(){data.updated=now();try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch{toast('Stockage saturé. Exportez votre sauvegarde et réduisez les photos.');return false}}
function toast(message){const n=document.createElement('div');n.className='toast';n.textContent=message;$('toast-root').append(n);setTimeout(()=>n.remove(),3400)}
function download(content,filename,mime='text/plain;charset=utf-8'){let b=new Blob([content],{type:mime});const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2500)}
function fileName(t,ext='txt'){return 'GRP_ANTBRO_'+String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\w-]+/g,'_').slice(0,65)+'_'+day()+'.'+ext}
function button(label,action,cls='secondary',attrs=''){return `<button type="button" class="btn ${cls}" data-action="${safe(action)}" ${attrs}>${label}</button>`}
function empty(title,desc,action,label){return `<div class="empty"><b>${safe(title)}</b>${safe(desc)}${action?`<div class="button-row" style="justify-content:center">${button(safe(label),action)}</div>`:''}</div>`}
function pageTitle(kicker,title,desc,action,label){return `<div class="page-head"><span class="eyebrow">${safe(kicker)}</span><h1>${safe(title)}</h1><p>${safe(desc)}</p>${action?`<div class="button-row">${button(safe(label),action,'')}</div>`:''}</div>`}
function header(label,icon,action,cta){return `<h2 class="panel-title"><span class="left"><span class="p-icon">${icon}</span>${safe(label)}</span>${action?`<button class="sub-action" data-action="${safe(action)}">${safe(cta||'Voir tout')} →</button>`:''}</h2>`}
function badge(s){let c=/confirm|termin|prêt|valid|actif|réalis/i.test(s)?'green':/attente|cours|prépar/i.test(s)?'blue':'';return `<span class="status ${c}">${safe(s||'À définir')}</span>`}
function djBy(id){return data.djs.find(x=>x.id===id)}
function progress(d){return Math.round((Array.isArray(d.steps)?d.steps.length:0)*100/MILESTONES.length)}
function photo(d){let p=urlSafe(d.photo);if(!p&&/^data:image\/(jpeg|png|webp);base64,/.test(d.photo||''))p=d.photo;return p?`style="background-image:linear-gradient(transparent,#08060680),url('${safe(p)}')"`:''}
function djTile(d){return `<button class="dj-tile" data-action="view-dj" data-id="${safe(d.id)}"><div class="dj-visual" ${photo(d)}>${d.photo?'':'♫'}</div><div class="dj-info">${badge(d.status||'À développer')}<strong>${safe(d.name)}</strong><small>${safe(d.genre||'Style à renseigner')} · ${progress(d)}% du parcours</small></div></button>`}
function groupRow(g){return `<button class="group-row" data-action="view-group" data-id="${safe(g.id)}"><span class="group-badge">${safe(g.abbr||'GRP')}</span><span class="g-name">${safe(g.name)}<span class="g-sub">${safe(g.kind||'Groupe')} ${g.link?'· lien configuré':'· lien à ajouter'}</span></span><span style="color:#f99b40;font-size:23px">›</span></button>`}
function getUpcoming(){return [...data.interviews].filter(x=>x.date&&new Date(x.date)>=new Date()).sort((a,b)=>a.date.localeCompare(b.date))[0]}
function mainDashboard(){const next=getUpcoming(),pending=data.posts.filter(x=>x.status==='À faire valider').length;return `<section class="hero"><div class="hero-inner"><span class="eyebrow">LE BUREAU CENTRAL DE GRP</span><h1>Un réseau.<br><em>Un seul bureau.</em></h1><p>Regrouper les espaces TikTok, accompagner les DJ et préparer chaque communication sans perdre l'historique du travail.</p><div class="button-row">${button('＋ Ajouter un DJ','new-dj','')}${button('✉ Préparer un dossier','mail','secondary')}</div></div></section>
 <div class="kpi-grid">${[['♫','ARTISTES SUIVIS',data.djs.length],['♣','ESPACES RÉPERTORIÉS',data.groups.length],['▣','ENTREVUES PLANIFIÉES',data.interviews.filter(x=>x.status==='Planifiée').length],['▤','OPPORTUNITÉS',data.bookings.filter(x=>x.status!=='Annulée').length]].map(([ico,l,n])=>`<div class="kpi"><span class="kpi-icon">${ico}</span><small>${l}</small><b>${n}</b></div>`).join('')}</div>
 <div class="workspace-grid"><section class="panel">${header('DJ & ARTISTES','★','djs','Voir tous les DJ')}${data.djs.length?`<div class="cards-grid">${data.djs.slice(0,4).map(djTile).join('')}</div>`:empty('Aucun artiste dans le bureau','Ajoutez la première fiche : elle alimentera ensuite les entrevues, le booking et les dossiers courriel.','new-dj','Créer une fiche DJ')}</section><section class="panel">${header('GROUPES GRP','♣','groups','Gérer les espaces')}${data.groups.slice(0,6).map(groupRow).join('')}${pending?`<p class="small-help">${pending} annonce(s) en attente de validation GRP.</p>`:''}</section></div>
 <div class="workspace-grid"><section class="panel">${header('ANTBRO LIVE','▣','interviews','Toutes les entrevues')}<div class="interview-cover"><div class="tagline">LIVE ARTIST INTERVIEWS</div><h3>${next?safe(djBy(next.djId)?.name||next.title||'Invité'): 'La prochaine entrevue se prépare ici'}</h3><p>${next?`${prettyDate(next.date)} · ${safe(next.time||'Heure à confirmer')}`:'Planifiez les invités, produisez les 50 questions et exportez leur dossier.'}</p></div><div class="button-row">${button('🎙 Préparer une entrevue','new-interview','')}${button('Questions / dossiers','interviews','secondary')}</div></section>
 <section class="panel">${header('PARCOURS & BOOKING','▥','djs','Voir les progressions')}${data.djs.length?data.djs.slice(0,3).map(d=>`<div class="resource-card" style="margin-bottom:9px"><div class="progress-name">${safe(d.name)}</div><div class="progress-track"><div class="progress-fill" style="width:${progress(d)}%"></div></div><small class="muted">${progress(d)}% · ${d.steps.length}/${MILESTONES.length} étapes</small><div class="button-row">${button('Ouvrir le parcours','view-dj','tiny secondary',`data-id="${safe(d.id)}"`)}</div></div>`).join(''):empty('Parcours à créer','Chaque DJ aura son suivi individuel en huit étapes, de la découverte au booking.')}<div class="button-row">${button('＋ Nouvelle opportunité','new-booking','secondary')}${button('Bilan général','reports','ghost')}</div></section></div>
 <section class="panel tv-home-spot">${header('ANTBRO TV · LES MONITEURS','▶','tv','Ouvrir la régie')}<div class="tv-home-banner"><div><span class="tagline">LIVE ARTIST INTERVIEWS · MEDIA HUB</span><h3>Les entrevues et les directs, au même endroit.</h3><p>Playlist YouTube, lien de direct, régie et écran de diffusion.</p></div><div class="tv-home-status">${data.media.onAir==='live'?'● DIRECT À L’ANTENNE':'▶ ARCHIVES À L’ANTENNE'}</div></div><div class="button-row">${button('▶ Ouvrir les moniteurs','tv','')}${button('⚙ Configurer les sources','media-edit','secondary')}</div></section>
 <div class="workspace-grid"><section class="panel">${header('BABILLARD CENTRAL','✦','announcements','Toutes les annonces')}${data.posts.length?data.posts.slice(-3).reverse().map(p=>`<div class="line-item"><div><strong>${safe(p.title)}</strong><small>${safe(p.status)} · ${prettyDate(p.date)}</small></div>${button('Ouvrir','view-post','tiny secondary',`data-id="${safe(p.id)}"`)}</div>`).join(''):empty('Aucune annonce','Les communications GRP sont préparées ici avant diffusion.')}<div class="button-row">${button('Créer une annonce','new-post','')}</div></section>
 <section class="panel">${header('COURRIELS & SAUVEGARDES','✉','mail','Ouvrir') }<p>Les informations du parcours se rassemblent dans un dossier cumulatif, puis deviennent un courriel prêt à envoyer.</p><div class="button-row">${button('✉ Générer un courriel','mail','')}${button('⇩ Sauvegarde complète','backup','secondary')}</div><div class="notice info">Les courriels sont préparés, jamais envoyés silencieusement. Le fichier JSON exporté peut être joint manuellement pour transférer les données.</div></section></div>`}
function renderDJs(){let xs=data.djs.filter(d=>[d.name,d.genre,d.city,d.status].join(' ').toLowerCase().includes(search.toLowerCase()));return pageTitle('ARTIST MANAGEMENT','DJ & artistes','Fiches, profils Hedliner, historique, progression et dossiers individuels.','new-dj','＋ Ajouter un DJ')+`<div class="page-toolbar"><input class="search-field" id="dj-search" placeholder="Rechercher un artiste, style, ville..." value="${safe(search)}" aria-label="Rechercher un DJ"><span class="muted">${xs.length} fiche(s)</span></div><div class="cards-grid" id="dj-cards">${xs.length?xs.map(djTile).join(''):empty('Aucun résultat','Ajoutez une fiche ou modifiez la recherche.','new-dj','Ajouter un DJ')}</div>`}
function renderGroups(){return pageTitle('COMMUNITY MANAGEMENT','Groupes GRP','Registre central des espaces, leurs missions, responsables et liens externes. Les groupes TikTok ne sont pas administrés automatiquement par cette application.','new-group','＋ Ajouter un espace')+`<div class="list-grid">${data.groups.map(g=>`<article class="resource-card"><span class="card-ico">♣</span><h3>${safe(g.name)}</h3><span class="pill">${safe(g.kind)}</span><p>${safe(g.mission)}</p><div class="card-actions">${button('Gérer la fiche','view-group','tiny secondary',`data-id="${safe(g.id)}"`)}${urlSafe(g.link)?`<a class="btn tiny ghost" href="${safe(urlSafe(g.link))}" target="_blank" rel="noopener noreferrer">Ouvrir le groupe ↗</a>`:''}</div></article>`).join('')}</div>`}
function renderInterviews(){return pageTitle('LIVE ARTIST INTERVIEWS','Entrevues Antbro','Calendrier des invités, questions personnalisées, préparation de diffusion et transmission du dossier.','new-interview','🎙 Planifier une entrevue')+`<div class="interview-cover"><span class="tagline">UNE HEURE AVEC L’ARTISTE</span><h3>50 questions. Un invité. Un dossier complet.</h3><p>Préparation structurée en français, avec adaptation possible pour une émission en anglais et traduction française.</p></div><div class="button-row tv-shortcut">${button('▶ Diffuser les entrevues dans ANTBRO TV','tv','')}${button('⚙ Régler la playlist YouTube','media-edit','secondary')}</div><section class="panel">${header('ÉMISSIONS ENREGISTRÉES','▣')}${data.interviews.length?`<div class="data-lines">${data.interviews.slice().reverse().map(x=>`<div class="line-item"><div><strong>${safe(djBy(x.djId)?.name||x.title)}</strong><small>${prettyDate(x.date)} · ${safe(x.time||'À fixer')} · ${safe(x.status)}</small></div><div class="line-actions">${button('Préparer 50 questions','questions','tiny',`data-id="${safe(x.id)}"`)}${urlSafe(x.replayUrl)?`<a class="btn tiny ghost" target="_blank" rel="noopener noreferrer" href="${safe(urlSafe(x.replayUrl))}">Voir la rediffusion ↗</a>`:''}${button('Modifier','edit-interview','tiny secondary',`data-id="${safe(x.id)}"`)}</div></div>`).join('')}</div>`:empty('Aucune émission enregistrée','Planifiez la première entrevue.','new-interview','Créer une entrevue')}</section>`}
function renderBooking(){return pageTitle('ARTIST BOOKING','Opportunités & booking','Suivez les démarches sans confondre une proposition avec un spectacle confirmé.','new-booking','＋ Nouvelle opportunité')+`<div class="list-grid">${data.bookings.length?data.bookings.slice().reverse().map(x=>`<article class="resource-card"><span class="card-ico">▤</span><h3>${safe(x.title)}</h3><p><b>${safe(djBy(x.djId)?.name||'Aucun DJ lié')}</b> · ${safe(x.place||'Lieu à confirmer')}</p>${badge(x.status)}<p>${prettyDate(x.date)} · ${safe(x.notes||'')}</p><div class="card-actions">${button('Modifier','edit-booking','tiny secondary',`data-id="${safe(x.id)}"`)}${button('Préparer le dossier','compose','tiny',`data-id="${safe(x.djId||'')}"`)}</div></article>`).join(''):empty('Aucune opportunité','Ajoutez une salle, un événement ou une démarche de représentation.','new-booking','Créer une opportunité')}</div>`}
function renderPosts(){return pageTitle('CENTRAL COMMUNICATION','Babillard & annonces','Préparez, classez et transmettez les annonces. L’approbation interne appartient aux responsables GRP.','new-post','✦ Nouvelle annonce')+`<div class="list-grid">${data.posts.length?data.posts.slice().reverse().map(p=>`<article class="resource-card"><span class="card-ico">✦</span><h3>${safe(p.title)}</h3>${badge(p.status)}<p>${safe(p.body||'')}</p><small class="muted">Destinataire : ${safe(p.target||'Tous les groupes')} · ${prettyDate(p.date)}</small><div class="card-actions">${button('Modifier','edit-post','tiny secondary',`data-id="${safe(p.id)}"`)}${button('Copier','copy-post','tiny ghost',`data-id="${safe(p.id)}"`)}</div></article>`).join(''):empty('Aucune annonce','Créez une annonce et transmettez-la à la direction concernée pour validation.','new-post','Créer une annonce')}</div>`}
function renderActivities(){let sorted=data.activities.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));return pageTitle('ARTIST JOURNAL','Journal & suivis','Enregistrez conversations, prises de contact, confirmations et prochaines actions. Chaque élément enrichit automatiquement le dossier du DJ.','new-activity','＋ Ajouter une information')+`<div class="panel-2col"><section class="panel">${header('HISTORIQUE','◷')}${sorted.length?`<div class="timeline">${sorted.map(a=>`<div class="timeline-item"><b>${safe(a.type)}</b> — ${safe(djBy(a.djId)?.name||'Sans DJ associé')}<p>${safe(a.note)}</p><small>${prettyDate(a.date)}</small><div class="button-row">${button('Modifier','edit-activity','tiny secondary',`data-id="${safe(a.id)}"`)}</div></div>`).join('')}</div>`:empty('Historique vide','Les échanges saisis ici apparaîtront dans les courriels cumulatifs.')}</section><section class="panel">${header('RELANCES & TÂCHES','☑')}<div class="data-lines">${data.tasks.map(t=>`<div class="line-item"><div><strong>${safe(t.title)}</strong><small>${safe(djBy(t.djId)?.name||'Général')} · ${prettyDate(t.date)} · ${t.done?'Terminée':'À faire'}</small></div><div class="line-actions">${button(t.done?'Réouvrir':'Terminer','toggle-task','tiny secondary',`data-id="${safe(t.id)}"`)}${button('Modifier','edit-task','tiny ghost',`data-id="${safe(t.id)}"`)}</div></div>`).join('')||empty('Aucune tâche','Ajoutez un suivi pour ne perdre aucune démarche.')} </div><div class="button-row">${button('＋ Planifier un suivi','new-task','')}</div></section></div>`}
function renderMail(){const has=data.djs.length;const d=has?data.djs[0]:null;return pageTitle('DOCUMENT CENTER','Courriels & dossiers','Regrouper toutes les informations d’un DJ, télécharger son dossier et préparer un courriel adressé aux destinataires configurés.')+`<div class="panel-2col"><section class="panel">${header('CONSTRUIRE UN DOSSIER CUMULATIF','✉')}<p>Le document se reconstruit avec la fiche DJ, les étapes validées, le journal, les entrevues, le booking et les suivis associés.</p><div class="form-field"><label for="mail-dj">Artiste concerné</label><select id="mail-dj"><option value="">Choisir un DJ...</option>${data.djs.map(x=>`<option value="${safe(x.id)}">${safe(x.name)}</option>`).join('')}</select></div><div class="button-row">${button('Générer le dossier et le courriel','compose-selected','')}${button('Configurer destinataires','settings','secondary')}</div>${has?'':`<div class="notice">Il faut d'abord créer au moins un dossier DJ.</div>`}<p class="small-help">L'ouverture d'un brouillon n'envoie aucun courriel. Vérifiez le destinataire et cliquez vous-même sur Envoyer dans votre messagerie.</p></section><section class="panel">${header('SAUVEGARDE COMPLÈTE','⇩')}<p>Exportez un fichier JSON de toutes les fiches GRP, puis joignez ce fichier à un message pour le conserver ou le transférer sur un autre appareil.</p><div class="button-row">${button('⇩ Exporter la sauvegarde','backup','')}${button('⇧ Partager la sauvegarde','share-backup','secondary')}${button('✉ Préparer un courriel de sauvegarde','backup-email','secondary')}${button('⇧ Importer un fichier','import','ghost')}</div><div class="notice info">Le courriel constitue une copie supplémentaire. Les données restent locales sur l'appareil tant qu'aucune base synchronisée n'a été raccordée.</div></section></div><section class="panel top-small">${header('DOCUMENTS PRÉPARÉS','▥')}<div class="data-lines">${data.mailHistory.length?data.mailHistory.slice(-12).reverse().map(x=>`<div class="line-item"><div><strong>${safe(x.title)}</strong><small>${prettyDate(x.date)} · ${safe(x.kind)} · ${x.sent?'Envoi déclaré':'Brouillon préparé'}</small></div><div class="line-actions">${button('Exporter TXT','export-mail','tiny secondary',`data-id="${safe(x.id)}"`)}${button(x.sent?'Envoyé ✓':'Marquer envoyé','mark-mail','tiny ghost',`data-id="${safe(x.id)}"`)}</div></div>`).join(''):empty('Aucun dossier préparé','Vos documents et courriels préparés apparaîtront dans ce registre local.')} </div></section>`}
function renderReports(){return pageTitle('ARTIST ANALYTICS','Bilans & progression','Résultats observables fondés sur les dossiers enregistrés, sans chiffres inventés.')+`<div class="kpi-grid">${[['♫','ARTISTES',data.djs.length],['▣','ENTREVUES TERMINÉES',data.interviews.filter(x=>x.status==='Réalisée').length],['▤','BOOKINGS CONFIRMÉS',data.bookings.filter(x=>x.status==='Confirmée').length],['☑','SUIVIS COMPLÉTÉS',data.tasks.filter(x=>x.done).length]].map(([i,l,n])=>`<div class="kpi"><span class="kpi-icon">${i}</span><small>${l}</small><b>${n}</b></div>`).join('')}</div><div class="workspace-grid"><section class="panel">${header('BILANS INDIVIDUELS','▥')}<div class="data-lines">${data.djs.map(d=>`<div class="line-item"><div><strong>${safe(d.name)}</strong><small>${progress(d)}% des huit étapes</small></div><div class="line-actions">${button('TXT','report-dj','tiny secondary',`data-id="${safe(d.id)}"`)}${button('Courriel','compose','tiny',`data-id="${safe(d.id)}"`)}</div></div>`).join('')||empty('Pas encore de bilan','Les rapports apparaîtront lorsque des DJ seront ajoutés.')}</div></section><section class="panel">${header('EXPORTS PROFESSIONNELS','⇩')}<p>Les données de votre bureau peuvent être conservées indépendamment du navigateur.</p><div class="button-row">${button('Exporter tous les DJ (CSV)','export-csv','')}${button('Exporter sauvegarde (JSON)','backup','secondary')}${button('Imprimer un bilan','print-report','ghost')}</div><div class="notice">Les informations rapportées reflètent uniquement les données saisies. Une réservation ne devient confirmée que lorsque son statut a été mis à jour après une confirmation réelle.</div></section></div>`}
function renderSettings(){return pageTitle('CONFIGURATION','Réglages & conservation','Adresses de destination, identité de signature, import/export et entretien du bureau.')+`<div class="panel-2col"><section class="panel">${header('COURRIELS DE DESTINATION','✉')}<form id="settings-form"><div class="form-field"><label>Destinataire principal (ex. Antbro)</label><input type="email" name="to" value="${safe(data.settings.to)}" placeholder="adresse@exemple.com"></div><div class="form-field"><label>Destinataire en copie (facultatif)</label><input type="email" name="cc" value="${safe(data.settings.cc)}" placeholder="copie@exemple.com"></div><div class="form-field"><label>Signature utilisée dans les dossiers</label><input name="signature" maxlength="150" value="${safe(data.settings.signature)}"></div><button class="btn" type="submit">Enregistrer les réglages</button></form><p class="small-help">Les adresses ne sont pas publiées dans le code. Elles sont propres à ce navigateur.</p></section><section class="panel">${header('PROTECTION DES FICHIERS','▥')}<p>Chaque appareil possède sa propre copie locale. Exporter permet d'archiver et de transférer volontairement les informations.</p><div class="button-row">${button('⇩ Sauvegarder JSON','backup','')}${button('⇧ Restaurer JSON','import','secondary')}${button('Exporter CSV','export-csv','ghost')}</div><div class="divider"></div><div class="notice">Pour une équipe multi-utilisateur, une authentification et une base sécurisée restent nécessaires. N'enregistrez pas de mots de passe, de données sensibles ou d'informations médicales dans les fiches.</div><div class="button-row">${button('Effacer les données locales','reset','danger')}</div></section></div><section class="panel top-small">${header('CADRE DES RESPONSABILITÉS','♣')}<p>Antbro et GRP contrôlent les décisions et les politiques de leurs groupes. R-Niel peut accompagner les DJ selon son mandat convenu. MEYDEN fournit l'outil et l'accompagnement artistique dans le cadre d'ententes distinctes. Un profil Hedliner, une inscription GRP et un contrat de représentation sont trois réalités différentes.</p><p>Aucune modification d'un groupe TikTok, adhésion, approbation officielle ou diffusion automatique n'est déclenchée depuis ce bureau.</p></section>`}

/* ANTBRO TV — studio double moniteur: sources YouTube et Twitch uniquement */
function mediaPlaylistId(raw){
 const x=String(raw||'').trim(); if(!x)return '';
 if(/^(?:PL|UU|OLAK5uy_|RD)[\w-]{6,}$/.test(x))return x;
 try{const u=new URL(x);let h=u.hostname.toLowerCase().replace(/^www\./,'');
  if(!['youtube.com','m.youtube.com','music.youtube.com','youtube-nocookie.com'].includes(h))return '';
  const list=u.searchParams.get('list')||'';
  return /^[\w-]{8,}$/.test(list)?list:'';
 }catch{return ''}
}
function mediaLiveSource(raw){
 const input=String(raw||'').trim(),url=urlSafe(input);if(!url)return null;
 let u=new URL(url),h=u.hostname.toLowerCase().replace(/^www\./,''),parts=u.pathname.split('/').filter(Boolean),id='';
 if(h==='youtu.be')id=parts[0]||'';
 else if(['youtube.com','m.youtube.com','music.youtube.com','youtube-nocookie.com'].includes(h)){
  if(parts[0]==='watch')id=u.searchParams.get('v')||'';
  if(['live','embed','shorts'].includes(parts[0]))id=parts[1]||'';
 }
 if(/^[\w-]{11}$/.test(id))return {kind:'YouTube',id,externalUrl:url,embedUrl:'https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id)+'?playsinline=1&autoplay=0&rel=0'};
 if(h==='twitch.tv'||h==='m.twitch.tv'){
  let ch=parts[0]||'';
  if(/^[A-Za-z0-9_]{3,25}$/.test(ch)&&!['videos','clips','directory','downloads'].includes(ch)){
   let embedUrl=location.protocol.startsWith('http')?'https://player.twitch.tv/?channel='+encodeURIComponent(ch)+'&parent='+encodeURIComponent(location.hostname)+'&autoplay=false&muted=false':'';
   return {kind:'Twitch',id:ch,externalUrl:url,embedUrl};
  }
 }
 if(h==='tiktok.com'||h==='m.tiktok.com'||h==='vm.tiktok.com')return {kind:'TikTok LIVE',externalUrl:url,embedUrl:'',reason:'La plateforme ne fournit pas ici de lecteur officiel pour les directs. Ouvrir ce lien sur TikTok.'};
 if(['youtube.com','m.youtube.com'].includes(h))return {kind:'Chaîne YouTube',externalUrl:url,embedUrl:'',reason:'Utilisez l’URL de la vidéo en direct (watch?v=… ou /live/ID) pour afficher le lecteur intégré.'};
 return {kind:'Lien externe',externalUrl:url,embedUrl:'',reason:'Ce service n’est pas pris en charge comme lecteur intégré. Le bouton ouvre le site officiel.'};
}
function mediaPlaylistEmbed(id){return id?'https://www.youtube-nocookie.com/embed/videoseries?list='+encodeURIComponent(id)+'&playsinline=1&autoplay=0&loop=1&rel=0':'';}
function mediaFrame(src,title){return `<iframe title="${safe(title)}" loading="lazy" src="${safe(src)}" allow="autoplay; encrypted-media; accelerometer; gyroscope; picture-in-picture; fullscreen; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`}
function monitorCard(type,publicView=false){
 const archives=type==='archives',id=mediaPlaylistId(data.media.playlistUrl),source=mediaLiveSource(data.media.liveUrl);
 const src=archives?mediaPlaylistEmbed(id):(source?.embedUrl||'');
 const link=archives?(id?'https://www.youtube.com/playlist?list='+encodeURIComponent(id):''):(source?.externalUrl||'');
 const title=archives?'ENTREVUES EN REDIFFUSION':'DIRECT ANTBRO LIVE';
 const desc=archives?'La playlist YouTube actualise la programmation lorsque de nouvelles entrevues y sont publiées.':(data.media.liveTitle||'ANTBRO LIVE');
 const issue=archives?'Ajoutez une playlist publique YouTube dans la régie.':source?(source.reason||'Lecteur du direct prêt. Appuyez sur Lecture.'):'Collez le lien d’un direct YouTube ou d’une chaîne Twitch.';
 return `<section class="tv-monitor ${data.media.onAir===type?'tv-onair':''}" aria-label="${title}">
 <div class="tv-monitor-top"><div><span class="tv-overline">${archives?'PLAYLIST · ARCHIVES':'● ÉMISSION · LIVE'}</span><h2>${title}</h2></div><span class="tv-source-tag">${archives?'YOUTUBE':source?source.kind.toUpperCase():'SOURCE À DÉFINIR'}</span></div>
 <div class="tv-screen" id="media-${type}-screen">${src?mediaFrame(src,title):`<div class="tv-empty"><span class="tv-television">${archives?'▣':'◉'}</span><strong>${archives?'Les émissions arrivent ici':'Le direct arrive ici'}</strong><p>${safe(issue)}</p>${link?`<a class="btn secondary" href="${safe(link)}" target="_blank" rel="noopener noreferrer">Ouvrir la source ↗</a>`:''}</div>`}</div>
 <div class="tv-screen-caption"><span>${safe(desc)}</span>${data.media.onAir===type?'<b class="tv-tag-active">À L’ANTENNE</b>':''}</div>
 <div class="tv-buttons">${button(archives?'Mettre les archives à l’antenne':'Passer en direct','media-onair',data.media.onAir===type?'secondary':'',`data-mode="${type}"`)}${button('⛶ Plein écran','media-fullscreen','secondary',`data-id="${type}"`)}${link?`<a class="btn ghost" target="_blank" rel="noopener noreferrer" href="${safe(link)}">Voir sur ${archives?'YouTube':safe(source?.kind||'la plateforme')} ↗</a>`:''}</div>
 </section>`
}
function renderTV(){const id=mediaPlaylistId(data.media.playlistUrl),source=mediaLiveSource(data.media.liveUrl);
 return `<div class="tv-page"><div class="tv-hero"><div><span class="eyebrow">ANTBRO | GRP INTERNATIONAL · MEDIA CENTER</span><h1>ANTBRO <em>TV</em></h1><p>Deux moniteurs. Une régie. Les entrevues archivées sur YouTube et les directs au même endroit.</p><div class="tv-hero-buttons">${button('⚙ Configurer les sources','media-edit','')}${button('⛶ Ouvrir l’écran de diffusion','media-open-public','secondary',`data-mode="${data.media.onAir}"`)}</div></div><span class="tv-broadcast-pill">${data.media.onAir==='live'?'● MODE DIRECT':'▶ MODE ARCHIVES'}</span></div>
 <div class="tv-regie"><div><span class="tv-overline">RÉGIE DE DIFFUSION</span><h3>Quel contenu est à l’antenne ?</h3><p>Choisissez manuellement la programmation. Les deux moniteurs restent accessibles pour l’écoute individuelle.</p></div><div class="tv-segment"><button type="button" class="${data.media.onAir==='archives'?'chosen':''}" data-action="media-onair" data-mode="archives">▶ Entrevues</button><button type="button" class="${data.media.onAir==='live'?'chosen':''}" data-action="media-onair" data-mode="live">● En direct</button></div></div>
 <div class="tv-dual">${monitorCard('archives')}${monitorCard('live')}</div>
 <section class="panel tv-management">${header('DIFFUSION & PARTAGE','◉')}<div class="tv-management-grid"><div><span class="tv-overline">SOURCE PLAYLIST</span><strong>${id?'Playlist YouTube enregistrée':'Aucune playlist configurée'}</strong><p>${id?'L’ajout de nouvelles vidéos à cette playlist ne nécessite pas de nouveau lien.':'Collez la playlist créée pour les entrevues d’Antbro.'}</p></div><div><span class="tv-overline">SOURCE DIRECT</span><strong>${source?source.kind+' configuré':'Aucun direct configuré'}</strong><p>${source?.embedUrl?'Un lecteur intégré est disponible pour cette adresse.':source?source.reason:'Collez l’URL d’une vidéo YouTube LIVE ou d’une chaîne Twitch.'}</p></div></div><div class="button-row">${button('⚙ Modifier les liens','media-edit','')}${button('Copier le lien public','media-copy-public','secondary',`data-mode="${data.media.onAir}"`)}${button('✉ Envoyer la configuration','media-share-config','ghost')}</div><p class="small-help">Le lien public fonctionne après publication de l’application sur un site HTTPS. Il contient les identifiants vidéo sélectionnés et ne synchronise pas les réglages entre appareils. Les directs ne sont pas détectés automatiquement; il faut activer puis terminer le mode direct manuellement.</p></section>
 </div>`
}
function mediaEdit(){
 modal('ANTBRO TV · Configurer les moniteurs',`<form id="media-form"><div class="form-field"><label for="tv-playlist-url">Moniteur 1 · lien playlist YouTube publique</label><input id="tv-playlist-url" name="playlistUrl" type="text" value="${safe(data.media.playlistUrl)}" placeholder="https://www.youtube.com/playlist?list=PL..." autocomplete="off"></div><div class="form-field"><label for="tv-live-url">Moniteur 2 · lien vidéo YouTube LIVE ou chaîne Twitch</label><input id="tv-live-url" name="liveUrl" type="url" value="${safe(data.media.liveUrl)}" placeholder="https://www.youtube.com/live/..." autocomplete="off"></div><div class="form-field"><label for="tv-live-title">Titre du direct</label><input id="tv-live-title" name="liveTitle" maxlength="130" value="${safe(data.media.liveTitle)}" placeholder="ANTBRO LIVE — Entrevue de la semaine"></div><div class="notice info">Le lecteur n’ajoute aucune vidéo à YouTube. Déposez d’abord les entrevues dans votre playlist. Une vidéo peut ne pas être intégrable selon les droits ou les paramètres YouTube. Les directs TikTok sont uniquement ouverts sur TikTok.</div><div class="button-row"><button type="submit" class="btn">✓ Enregistrer les liens</button>${button('Annuler','close','secondary')}</div></form>`)
}
function submitMedia(f){
 const v=Object.fromEntries(new FormData(f)),play=(v.playlistUrl||'').trim(),live=(v.liveUrl||'').trim(),title=(v.liveTitle||'').trim();
 if(play&&!mediaPlaylistId(play)){toast('Playlist non reconnue. Utilisez un lien youtube.com/playlist?list=… ou son identifiant.');return}
 if(live&&!mediaLiveSource(live)){toast('Lien de direct invalide. Utilisez une adresse HTTPS YouTube, Twitch ou TikTok.');return}
 data.media.playlistUrl=play;data.media.liveUrl=live;data.media.liveTitle=title||'ANTBRO LIVE';
 if(data.media.onAir==='live'&&!mediaLiveSource(live)?.embedUrl)data.media.onAir='archives';
 persist();closeModal();if(page!=='tv')navigate('tv');else render();toast('Les deux sources ont été enregistrées dans ce bureau.');
}
function mediaOnAir(mode){
 if(!['archives','live'].includes(mode))return;
 if(mode==='live'&&!mediaLiveSource(data.media.liveUrl)?.embedUrl){toast('Pour passer en direct, ajoutez une URL YouTube LIVE ou Twitch intégrable, puis publiez l’application sur HTTPS pour Twitch.');return}
 if(mode==='archives'&&!mediaPlaylistId(data.media.playlistUrl)){toast('Configurez la playlist YouTube pour activer le canal archives.');return}
 data.media.onAir=mode;persist();render();toast(mode==='live'?'Direct sélectionné pour l’écran public.':'Programmation revenue aux entrevues.');
}
function mediaPublicUrl(mode){
 const q=new URL(location.href);q.search='';q.hash='';q.searchParams.set('monitor','1');q.searchParams.set('mode',mode==='live'?'live':'archives');
 const id=mediaPlaylistId(data.media.playlistUrl);if(id)q.searchParams.set('playlist',id);
 const src=mediaLiveSource(data.media.liveUrl);if(src){if(src.kind==='YouTube')q.searchParams.set('live','yt:'+src.id);else if(src.kind==='Twitch')q.searchParams.set('live','tw:'+src.id);else q.searchParams.set('live','external:'+src.externalUrl)}
 if(data.media.liveTitle)q.searchParams.set('title',data.media.liveTitle);
 return q.href;
}
function mediaOpenPublic(mode){const url=mediaPublicUrl(mode);const newTab=window.open(url,'_blank');if(newTab)newTab.opener=null;else window.location.assign(url)}
function mediaCopyPublic(mode){if(!location.protocol.startsWith('http'))return toast('Ouvrez la version publiée sur Vercel pour copier une adresse publique partageable.');if(mode==='live'&&!mediaLiveSource(data.media.liveUrl))return toast('Aucun direct enregistré.');if(mode==='archives'&&!mediaPlaylistId(data.media.playlistUrl))return toast('Aucune playlist enregistrée.');copyText(mediaPublicUrl(mode))}
function mediaFullscreen(which){let e=document.getElementById('media-'+which+'-screen');if(!e)return toast('Moniteur indisponible.');if(document.fullscreenElement)return document.exitFullscreen?.();if(e.requestFullscreen)e.requestFullscreen().catch(()=>toast('Le plein écran n’est pas autorisé dans ce navigateur.'));else toast('Plein écran indisponible sur cet appareil.');}
function mediaShareConfig(){const pl=data.media.playlistUrl||'(non définie)',li=data.media.liveUrl||'(non défini)';createMail('Configuration ANTBRO TV','ANTBRO TV — Régie et liens de diffusion — '+day(),`ANTBRO × GRP INTERNATIONAL — RÉGIE TV\n\nPlaylist des entrevues : ${pl}\nDirect : ${li}\nTitre : ${data.media.liveTitle}\nProgrammation : ${data.media.onAir==='live'?'Direct':'Archives'}\n\nOuvrez le bureau et collez ces liens dans ANTBRO TV pour restaurer les sources sur un autre appareil. Les changements locaux ne sont pas encore synchronisés automatiquement.\n\n${data.settings.signature}`,'Configuration TV')}
function renderPublicMonitor(){
 const q=new URLSearchParams(location.search),pl=q.get('playlist')||'',live=q.get('live')||'',mode=q.get('mode')==='live'?'live':'archives';
 let src='',kind='',external='';
 if(mode==='archives'&&/^[\w-]{8,}$/.test(pl)){src=mediaPlaylistEmbed(pl);kind='ENTREVUES · PLAYLIST YOUTUBE';external='https://www.youtube.com/playlist?list='+encodeURIComponent(pl)}
 if(mode==='live'){
  let l=live.slice(3);if(live.startsWith('yt:')&&/^[\w-]{11}$/.test(l)){src='https://www.youtube-nocookie.com/embed/'+encodeURIComponent(l)+'?playsinline=1&autoplay=0';kind='DIRECT · YOUTUBE';external='https://www.youtube.com/watch?v='+encodeURIComponent(l)}
  else if(live.startsWith('tw:')&&/^[a-zA-Z0-9_]{3,25}$/.test(l)){kind='DIRECT · TWITCH';external='https://www.twitch.tv/'+l;if(location.protocol.startsWith('http'))src='https://player.twitch.tv/?channel='+encodeURIComponent(l)+'&parent='+encodeURIComponent(location.hostname)+'&autoplay=false'}
  else if(live.startsWith('external:')){kind='DIRECT · PLATEFORME EXTERNE';external=urlSafe(live.slice(9))}
 }
 let fallback=(!src&&mode==='live')?'Cette diffusion ne peut pas être intégrée dans le site. Ouvrez la source originale.':'Configurez le lien de la playlist dans la régie d’Antbro.';
 const logo=document.querySelector('.brand img')?.src||'./assets/antbro-brand.png';
 document.body.classList.add('public-monitor-mode');
 document.body.innerHTML=`<main class="tv-public"><header class="tv-public-head"><div class="tv-public-brand"><img src="${safe(logo)}" alt="ANTBRO GRP International"><div><strong>ANTBRO <span>TV</span></strong><small>${safe(kind||'MEDIA CHANNEL')}</small></div></div><span class="tv-pub-status">${mode==='live'?'● LIVE':'▶ REPLAY'}</span></header><section class="tv-public-stage" id="media-public-screen">${src?mediaFrame(src,kind||'ANTBRO TV'):`<div class="tv-empty"><span class="tv-television">◉</span><strong>ANTBRO TV</strong><p>${safe(fallback)}</p></div>`}</section><section class="tv-public-footer"><div><h1>${mode==='live'?safe(q.get('title')||'ANTBRO LIVE'):'LIVE ARTIST INTERVIEWS'}</h1><p>${mode==='live'?'Les directs de GRP International':'Les entrevues d’Antbro en rediffusion'}</p></div><div class="button-row">${button('⛶ Plein écran','media-fullscreen','secondary','data-id="public"')}${external?`<a class="btn ghost" href="${safe(external)}" target="_blank" rel="noopener noreferrer">Ouvrir sur la plateforme ↗</a>`:''}</div></section><div class="tv-public-credit">ANTBRO × GRP INTERNATIONAL · Bureau conçu par MEYDEN</div></main>`;
}

function navigate(p){if(!PAGES.some(x=>x[0]===p))return;page=p;search='';closeModal();render();scrollTo({top:0,behavior:'instant'});document.getElementById('sidebar').classList.remove('open')}
function render(){const views={dashboard:mainDashboard,djs:renderDJs,groups:renderGroups,interviews:renderInterviews,tv:renderTV,booking:renderBooking,announcements:renderPosts,activities:renderActivities,mail:renderMail,reports:renderReports,settings:renderSettings};$('app').innerHTML=`<div class="content">${(views[page]||mainDashboard)()}</div>`;$('nav').innerHTML=PAGES.map(([id,label,ico])=>`<button class="nav-item ${id===page?'active':''}" data-nav="${id}"><span class="nav-ico">${ico}</span>${safe(label)}</button>`).join('');$('bottom-nav').innerHTML=[['dashboard','Accueil','⌂'],['djs','DJ','♫'],['groups','Groupes','♣'],['tv','TV','▶']].map(([id,label,ico])=>`<button class="${page===id?'active':''}" data-nav="${id}"><span class="b-icon">${ico}</span>${label}</button>`).join('');}
function modal(title,body){$('modal-root').innerHTML=`<div class="modal-cover" id="modal-cover"><div class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-head"><div><span class="eyebrow">ANTBRO × GRP</span><h2>${safe(title)}</h2></div><button class="close-modal" type="button" data-action="close" aria-label="Fermer">×</button></div>${body}</div></div>`;document.querySelector('.modal input, .modal textarea, .modal button')?.focus();}
function closeModal(){$('modal-root').innerHTML=''}
function field(name,label,value='',kind='text',extra=''){let body=kind==='textarea'?`<textarea name="${name}" ${extra}>${safe(value)}</textarea>`:kind.startsWith('select:')?`<select name="${name}">${kind.slice(7).split('|').map(v=>`<option value="${safe(v)}" ${String(value)===v?'selected':''}>${safe(v)}</option>`).join('')}</select>`:`<input name="${name}" type="${kind}" value="${safe(value)}" ${extra}>`;return `<div class="form-field"><label>${safe(label)}</label>${body}</div>`}
function formButtons(type,exists){return `<div class="button-row"><button type="submit" class="btn">✓ Enregistrer</button>${exists?button('Supprimer','delete-record','danger',`data-kind="${safe(type)}" data-id="${safe(exists)}"`):''}${button('Annuler','close','secondary')}</div>`}
function editForm(type,id){let lookup={dj:'djs',group:'groups',interview:'interviews',booking:'bookings',post:'posts',activity:'activities',task:'tasks'};let coll=lookup[type];if(!coll)return;let rec=id?data[coll].find(x=>x.id===id):null;let x=rec||{};const djOpts=`<option value="">— Sans artiste —</option>${data.djs.map(d=>`<option value="${safe(d.id)}" ${d.id===x.djId?'selected':''}>${safe(d.name)}</option>`).join('')}`;const selectDj=`<div class="form-field"><label>DJ associé au dossier</label><select name="djId">${djOpts}</select></div>`;let fields='';let titles={dj:'Fiche DJ',group:'Groupe GRP',interview:'Entrevue Antbro',booking:'Opportunité de booking',post:'Annonce',activity:'Information du parcours',task:'Suivi / tâche'};
if(type==='dj')fields=`<div class="form-grid">${field('name','Nom de scène',x.name,'text','required maxlength="100"')}${field('genre','Style musical',x.genre,'text','maxlength="100"')}${field('city','Ville / région',x.city,'text','maxlength="100"')}${field('status','Situation artistique',x.status||'Découvert','select:Découvert|Contacté|En développement|Prêt pour entrevue|En promotion|Prêt pour booking')}</div><div class="form-grid">${field('tiktok','Profil TikTok (URL)',x.tiktok,'url','placeholder="https://..."')}${field('hedliner','Profil Hedliner (URL)',x.hedliner,'url','placeholder="https://..."')}</div>${field('photo','URL d’une photo autorisée (facultatif)',/^data:/.test(x.photo||'')?'':x.photo,'url','placeholder="https://..."')}<div class="form-field"><label>Ou importer une photo (compressée, conservée localement)</label><input id="photo-upload" type="file" accept="image/png,image/jpeg,image/webp"></div>${field('notes','Observations professionnelles non sensibles',x.notes,'textarea','maxlength="3000"')}`;
if(type==='group')fields=`<div class="form-grid">${field('name','Nom du groupe',x.name,'text','required maxlength="100"')}${field('abbr','Abréviation',x.abbr,'text','maxlength="6"')}${field('kind','Type d’espace',x.kind||'Communauté','select:Organisation|Apprentissage|Communauté|Émission|Coordination|Autre')}${field('lead','Responsable (si confirmé)',x.lead,'text','maxlength="100"')}</div>${field('mission','Mission',x.mission,'textarea','maxlength="1000"')}${field('rules','Règles proposées / approuvées',x.rules,'textarea','maxlength="1000"')}${field('link','Lien externe vérifié du groupe',x.link,'url','placeholder="https://..."')}`;
if(type==='interview')fields=`${selectDj}<div class="form-grid">${field('title','Titre ou invité si hors répertoire',x.title,'text','maxlength="120"')}${field('date','Date prévue',x.date,'date')}${field('time','Heure',x.time,'time')}${field('status','État',x.status||'Planifiée','select:À proposer|Planifiée|Préparée|Réalisée|Annulée')}</div>${field('notes','Notes de préparation / angle éditorial',x.notes,'textarea','maxlength="2500"')}${field('replayUrl','Lien YouTube de la rediffusion (facultatif)',x.replayUrl,'url','placeholder="https://www.youtube.com/watch?v=..."')}`;
if(type==='booking')fields=`${selectDj}${field('title','Occasion / événement',x.title,'text','required maxlength="160"')}<div class="form-grid">${field('place','Salle / organisateur',x.place,'text','maxlength="180"')}${field('date','Date envisagée',x.date,'date')}${field('status','Statut (ne confirmer qu’après accord)',x.status||'Prospection','select:Prospection|Proposition envoyée|En négociation|Confirmée|Terminée|Refusée|Annulée')}${field('fee','Cachet proposé (facultatif)',x.fee,'text','maxlength="80"')}</div>${field('notes','Détails, conditions et prochaine étape',x.notes,'textarea','maxlength="2500"')}`;
if(type==='post')fields=`${field('title','Titre de l’annonce',x.title,'text','required maxlength="150"')}<div class="form-grid">${field('target','Espace concerné',x.target||'Tous les groupes','select:Tous les groupes|GRP International|GRP Knowledge|GRP QB|GRP Fans|JRP|Antbro Live')}${field('status','État éditorial',x.status||'Brouillon','select:Brouillon|À faire valider|Validé hors application|Diffusé manuellement')}</div>${field('body','Message de l’annonce',x.body,'textarea','required maxlength="5500"')}`;
if(type==='activity')fields=`${selectDj}<div class="form-grid">${field('type','Type de démarche',x.type||'Conversation','select:Conversation|Découverte|Contact|Live|Courriel|Décision|Promotion|Booking|Autre')}${field('date','Date',x.date||day(),'date')}</div>${field('note','Information recueillie / résultat',x.note,'textarea','required maxlength="3500"')}`;
if(type==='task')fields=`${selectDj}${field('title','Action à réaliser',x.title,'text','required maxlength="220"')}<div class="form-grid">${field('date','Échéance',x.date,'date')}${field('status','Suivi',x.done?'Terminée':'À faire','select:À faire|Terminée')}</div>${field('notes','Contexte / suivi',x.notes,'textarea','maxlength="2000"')}`;
modal((rec?'Modifier · ':'Créer · ')+titles[type],`<form id="entity-form" data-entity="${type}" data-id="${safe(id||'')}">${fields}${formButtons(type,id)}</form>`)}
function viewDJ(id){let d=djBy(id);if(!d)return;const a=data.activities.filter(x=>x.djId===id).slice().reverse();modal('Dossier artiste · '+d.name,`<div class="form-grid"><div><div class="eyebrow">ARTIST DEVELOPMENT JOURNEY</div><h2 style="margin:8px 0">${safe(d.name)}</h2><p>${safe(d.genre||'Style non renseigné')} · ${safe(d.city||'Région non renseignée')}</p>${badge(d.status)}<p>${safe(d.notes||'')}</p></div><div><div class="progress-name">${progress(d)}% de progression</div><div class="progress-track"><div class="progress-fill" style="width:${progress(d)}%"></div></div><p class="small-help">Les étapes sont validées manuellement à partir des éléments obtenus.</p></div></div><div class="divider"></div><h3>Huit étapes du parcours</h3><div class="steps-grid">${MILESTONES.map((s,i)=>`<button class="step ${d.steps.includes(i)?'done':''}" type="button" data-action="toggle-step" data-id="${safe(id)}" data-step="${i}">${d.steps.includes(i)?'✓ ':'○ '}${safe(s)}</button>`).join('')}</div><div class="divider"></div><h3>Historique associé</h3>${a.length?`<div class="timeline">${a.map(x=>`<div class="timeline-item"><b>${safe(x.type)}</b><p>${safe(x.note)}</p><small>${prettyDate(x.date)}</small></div>`).join('')}</div>`:empty('Aucun échange enregistré','Ajoutez des informations au journal pour enrichir le dossier et les courriels.')}${[d.tiktok,d.hedliner].filter(urlSafe).map(l=>`<a href="${safe(urlSafe(l))}" target="_blank" rel="noopener noreferrer" class="btn tiny ghost">Ouvrir le profil ↗</a>`).join(' ')}<div class="button-row">${button('Modifier la fiche','edit-dj','secondary',`data-id="${safe(id)}"`)}${button('＋ Historique','activity-for-dj','secondary',`data-id="${safe(id)}"`)}${button('✉ Dossier & courriel','compose','',`data-id="${safe(id)}"`)}${button('⇩ Bilan TXT','report-dj','ghost',`data-id="${safe(id)}"`)}</div>`)}
function viewGroup(id){const g=data.groups.find(x=>x.id===id);if(!g)return;modal('Espace · '+g.name,`<h3>${safe(g.kind)}</h3><p>${safe(g.mission)}</p><div class="notice"><b>Règle :</b> ${safe(g.rules||'À définir par GRP')}</div><p>Responsable : ${safe(g.lead||'À confirmer')}</p><div class="button-row">${button('Modifier cet espace','edit-group','',`data-id="${safe(id)}"`)}${button('Copier les informations','copy-group','secondary',`data-id="${safe(id)}"`)}${urlSafe(g.link)?`<a class="btn ghost" target="_blank" rel="noopener noreferrer" href="${safe(urlSafe(g.link))}">Lien du groupe ↗</a>`:''}</div><div class="small-help">Les paramètres et les membres TikTok ne sont pas modifiés par cette fiche.</div>`)}
function viewPost(id){let p=data.posts.find(x=>x.id===id);if(!p)return;modal(p.title,`<div class="pill">${safe(p.status)}</div><p>${safe(p.body).replace(/\n/g,'<br>')}</p><p class="small-help">Cible : ${safe(p.target)} · créé le ${prettyDate(p.date)}</p><div class="button-row">${button('Modifier','edit-post','secondary',`data-id="${safe(id)}"`)}${button('Copier le message','copy-post','',`data-id="${safe(id)}"`)}</div>`)}
function reportForDJ(d){let a=data.activities.filter(x=>x.djId===d.id).sort((x,y)=>(x.date||'').localeCompare(y.date||'')), b=data.bookings.filter(x=>x.djId===d.id),i=data.interviews.filter(x=>x.djId===d.id),t=data.tasks.filter(x=>x.djId===d.id),lines=[];lines.push('GRP INTERNATIONAL × ANTBRO — DOSSIER ARTISTE','Document de suivi généré le '+new Date().toLocaleString('fr-CA'),'','ARTISTE : '+d.name,'Style : '+(d.genre||'À compléter'),'Ville/région : '+(d.city||'À compléter'),'Situation artistique : '+(d.status||'À définir'),'TikTok : '+(d.tiktok||'—'),'Hedliner : '+(d.hedliner||'—'),'Progression : '+progress(d)+' % ('+d.steps.length+'/'+MILESTONES.length+' jalons)','', 'ÉTAPES RÉALISÉES',...MILESTONES.map((m,n)=>(d.steps.includes(n)?'[✓] ':'[ ] ')+m),'','NOTES DE DOSSIER',d.notes||'Aucune note','',`JOURNAL DES ÉCHANGES (${a.length})`,...((a.length?a.map(x=>`${prettyDate(x.date)} · ${x.type} : ${x.note}`):['Aucune entrée'])),'',`ENTREVUES (${i.length})`,...((i.length?i.map(x=>`${prettyDate(x.date)} · ${x.status} · ${x.notes||x.title||'Sans note'}`):['Aucune entrevue'])),'',`BOOKING ET OPPORTUNITÉS (${b.length})`,...((b.length?b.map(x=>`${x.title} · ${x.place||'Salle à confirmer'} · ${prettyDate(x.date)} · ${x.status} · Cachet proposé : ${x.fee||'—'} · ${x.notes||''}`):['Aucune opportunité'])),'',`SUIVIS (${t.length})`,...((t.length?t.map(x=>`${x.done?'[✓]':'[ ]'} ${x.title} · ${prettyDate(x.date)} · ${x.notes||''}`):['Aucune tâche'])),'','REMARQUES','Les informations proviennent des saisies du bureau. Les décisions internes GRP, les adhésions, la représentation et les engagements contractuels doivent être confirmés séparément.','',data.settings.signature||'ANTBRO | GRP INTERNATIONAL');return lines.join('\n')}
function makeQuestions(x){let name=djBy(x.djId)?.name||x.title||'cet artiste',style=djBy(x.djId)?.genre||'votre univers';let sections=[['Présentation', ['Comment aimeriez-vous qu’on vous présente au public?','Quel moment vous a donné envie de créer?','Quelle est l’origine de votre nom d’artiste?','Qu’est-ce qui vous distingue comme artiste?','D’où vient votre énergie créative?','Quelle place la musique occupe-t-elle dans votre quotidien?','Quel est le premier souvenir musical marquant?','Qui vous a encouragé au départ?','Comment décririez-vous votre son à une personne qui ne vous connaît pas?','Quelle émotion voulez-vous transmettre?']],['Parcours',['Comment votre premier projet a-t-il commencé?','Quelle a été votre première scène ou performance?','Quelle difficulté vous a fait évoluer?','Quelle décision a changé votre parcours?','Comment préparez-vous un nouveau projet?','Qu’avez-vous appris en travaillant avec d’autres artistes?','Quel souvenir de scène vous rend fier?','Y a-t-il une erreur que vous ne referiez plus?','Comment mesurez-vous personnellement votre progression?','Quelle rencontre artistique vous a particulièrement marqué?']],['Création',['Comment choisissez-vous vos influences?','Quel rôle joue l’improvisation dans votre méthode?','Comment se construit une performance réussie?','Quel élément du processus créatif vous surprend encore?','Quelle importance donnez-vous aux paroles ou aux textures sonores?','Quelle place occupent les outils numériques dans votre travail?','Comment choisissez-vous les pièces à présenter au public?','Comment préparez-vous vos enregistrements?','Qu’aimez-vous le plus partager avec votre équipe?','De quel projet voulez-vous parler aujourd’hui?']],['Public & réseau',['Quel type d’échange recherchez-vous avec vos fans?','Comment choisissez-vous les lives auxquels participer?','Que vous apporte le contact avec les autres artistes?','Quel conseil donneriez-vous à quelqu’un qui débute?','Quelle est votre relation avec les réseaux sociaux?','Comment faites-vous connaître vos nouveautés?','Quel rôle les communautés musicales peuvent-elles jouer?','Qu’attendez-vous d’une collaboration professionnelle?','Que signifie pour vous une scène inclusive et respectueuse?','Quel message souhaitez-vous adresser à votre communauté?']],['Avenir',['Quel est votre prochain objectif réaliste?','Quelles scènes ou expériences aimeriez-vous explorer?','Qu’aimeriez-vous apprendre cette année?','Quel serait votre projet de collaboration idéal?','Quels moyens vous aideraient le plus à avancer?','Quelle habitude souhaitez-vous développer?','Quelles valeurs doivent guider vos partenariats?','Comment aimeriez-vous que votre travail soit reconnu?','Qu’aimeriez-vous accomplir d’ici un an?','Quelle dernière chose souhaitez-vous dire au public?']]];let n=0;return `ANTBRO LIVE — DOSSIER D’ENTREVUE\nInvité : ${name}\nUnivers musical : ${style}\nDate : ${prettyDate(x.date)} · ${x.time||'heure à confirmer'}\nDurée cible : 60 minutes\nLangue : anglais avec traduction française selon disponibilité, à convenir avec l’invité\nNotes : ${x.notes||'—'}\n\nDÉROULEMENT PROPOSÉ\n0–5 min : Accueil et présentation\n5–20 min : Origines et parcours\n20–40 min : Création et oeuvres\n40–55 min : Communauté, projets et questions\n55–60 min : Conclusion\n\n50 QUESTIONS\n`+sections.map(([t,arr])=>'\n'+t.toUpperCase()+'\n'+arr.map(q=>`${String(++n).padStart(2,'0')}. ${q}`).join('\n')).join('\n')+'\n\nCes questions sont des propositions éditoriales à adapter. Respecter la volonté de l’invité et ses droits sur les contenus.'}
function textEmail(id){const d=djBy(id);return d?reportForDJ(d):''}
function compose(id){const d=djBy(id);if(!d){toast('Choisissez d’abord un DJ.');return}const subject=`ANTBRO / GRP — dossier ${d.name} — ${day()}`;const body=textEmail(id);createMail('Dossier artistique · '+d.name,subject,body,'Dossier DJ')}
function createMail(title,subject,body,kind='Document'){const m={id:uid(),title,subject,body,kind,date:now(),sent:false};data.mailHistory.push(m);persist();mailDraft=m;renderMailModal(m)}
function renderMailModal(m){modal('Dossier & courriel préparé',`<form id="mail-form" data-id="${safe(m.id)}"><div class="form-grid">${field('to','À (destinataire principal)',data.settings.to,'email','placeholder="adresse@exemple.com"')}${field('cc','Copie (facultatif)',data.settings.cc,'email','placeholder="copie@exemple.com"')}</div>${field('subject','Objet',m.subject,'text','required')}<div class="form-field"><label>Texte modifiable du dossier</label><textarea id="mail-body" class="editor" name="body">${safe(m.body)}</textarea></div><p class="form-help">Le fichier texte et le brouillon de messagerie sont deux formes de conservation du même dossier. L’ouverture de la messagerie ne constitue pas un envoi. Pour partager une sauvegarde JSON, joignez le fichier manuellement.</p><div class="button-row"><button type="submit" class="btn">✉ Ouvrir le courriel prêt à envoyer</button>${button('⇩ Télécharger TXT','mail-txt','secondary',`data-id="${safe(m.id)}"`)}${button('⇧ Partager fichier','mail-share','secondary',`data-id="${safe(m.id)}"`)}${button('Copier','mail-copy','ghost',`data-id="${safe(m.id)}"`)}</div></form>`)}
function csvQ(x){return '"'+String(x??'').replace(/"/g,'""')+'"'}
function exportCSV(){const arr=[['Nom de scène','Style','Ville','Statut artistique','TikTok','Hedliner','Progression','Notes'],...data.djs.map(x=>[x.name,x.genre,x.city,x.status,x.tiktok,x.hedliner,progress(x)+'%',x.notes])];download('\uFEFF'+arr.map(r=>r.map(csvQ).join(';')).join('\r\n'),fileName('artistes','csv'),'text/csv;charset=utf-8');toast('Répertoire CSV créé.')}
function backup(){const copy=JSON.stringify({...data,exportedAt:now()},null,2);download(copy,fileName('sauvegarde_complete','json'),'application/json;charset=utf-8');toast('Sauvegarde JSON téléchargée. Conservez-la en lieu sûr.')}
async function shareFile(filename,content,mime,title,text){
 const f=new File([content],filename,{type:mime});
 if(navigator.share&&navigator.canShare?.({files:[f]})){
  try{await navigator.share({files:[f],title,text});toast('Fichier transmis à l’application de partage. Vérifiez son envoi.');return;}
  catch(e){if(e.name==='AbortError'){toast('Partage annulé.');return;}}
 }
 download(content,filename,mime);toast('Partage de fichiers indisponible : fichier téléchargé. Joignez-le manuellement à votre courriel.');
}
function shareBackup(){const content=JSON.stringify({...data,exportedAt:now()},null,2);return shareFile(fileName('sauvegarde_complete','json'),content,'application/json','Sauvegarde GRP International / Antbro','Sauvegarde du bureau Antbro GRP International.');}
function backupEmail(){createMail('Sauvegarde des données GRP','GRP / ANTBRO — copie de sauvegarde — '+day(),'Bonjour,\n\nVoici une copie de sauvegarde du Bureau GRP International — Antbro, exportée le '+new Date().toLocaleString('fr-CA')+'.\n\nVeuillez joindre manuellement le fichier JSON téléchargé dans le bureau :\n'+fileName('sauvegarde_complete','json')+'\n\nCe message seul ne contient PAS la sauvegarde; la pièce jointe JSON est indispensable.\n\n'+data.settings.signature,'Sauvegarde')}
function importJSON(f){if(!f||f.size>8_000_000){toast('Fichier absent ou trop volumineux (max. 8 Mo).');return}const rd=new FileReader();rd.onload=()=>{try{let x=JSON.parse(rd.result);if(!x||typeof x!=='object'||!Array.isArray(x.djs)||!Array.isArray(x.groups))throw Error('format');if(![4,5].includes(Number(x.version)))throw Error('version');if(!confirm('Importer remplacera les données locales actuelles. Avez-vous conservé une sauvegarde de celles-ci?'))return;let fresh=START();for(const k of ['djs','groups','interviews','bookings','posts','activities','tasks','mailHistory'])fresh[k]=Array.isArray(x[k])?x[k].slice(0,10000):[];fresh.settings={...fresh.settings,...(x.settings||{})};fresh.media={...MEDIA_DEFAULT,...(x.media||{})};data=fresh;persist();navigate('dashboard');toast('Sauvegarde restaurée sur cet appareil.')}catch{toast('Sauvegarde non reconnue (sauvegarde GRP v4 ou v5 requise).')}};rd.readAsText(f)}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('Texte copié.')}catch{let e=document.createElement('textarea');e.value=t;document.body.append(e);e.select();try{document.execCommand('copy');toast('Texte copié.')}catch{toast('La copie a échoué.')}e.remove()}}
function handleAction(el){let a=el.dataset.action,id=el.dataset.id;if(!a)return;
const jumps={dashboard:'dashboard',djs:'djs',groups:'groups',interviews:'interviews',booking:'booking',announcements:'announcements',activities:'activities',mail:'mail',reports:'reports',settings:'settings',tv:'tv'};if(jumps[a])return navigate(jumps[a]);
if(a==='media-edit')return mediaEdit();if(a==='media-onair')return mediaOnAir(el.dataset.mode);if(a==='media-open-public')return mediaOpenPublic(el.dataset.mode);if(a==='media-copy-public')return mediaCopyPublic(el.dataset.mode);if(a==='media-fullscreen')return mediaFullscreen(el.dataset.id);if(a==='media-share-config')return mediaShareConfig();if(a==='close')return closeModal();if(a==='new-dj')return editForm('dj');if(a==='new-group')return editForm('group');if(a==='new-interview')return editForm('interview');if(a==='new-booking')return editForm('booking');if(a==='new-post')return editForm('post');if(a==='new-activity')return editForm('activity');if(a==='new-task')return editForm('task');
for(const t of ['dj','group','interview','booking','post','activity','task'])if(a==='edit-'+t)return editForm(t,id);
if(a==='view-dj')return viewDJ(id);if(a==='view-group')return viewGroup(id);if(a==='view-post')return viewPost(id);
if(a==='activity-for-dj'){editForm('activity');const e=$('modal-root').querySelector('[name="djId"]');if(e)e.value=id;return}
if(a==='toggle-step'){const d=djBy(id),n=Number(el.dataset.step);if(!d||!Number.isInteger(n)||n<0||n>=8)return;d.steps=d.steps.includes(n)?d.steps.filter(y=>y!==n):[...d.steps,n].sort();persist();viewDJ(id);return}
if(a==='toggle-task'){const t=data.tasks.find(x=>x.id===id);if(t){t.done=!t.done;persist();render()}return}
if(a==='report-dj'){const d=djBy(id);if(d){download(reportForDJ(d),fileName('bilan_'+d.name));toast('Bilan de '+d.name+' téléchargé.')}return}
if(a==='questions'){const x=data.interviews.find(z=>z.id===id);if(x){const txt=makeQuestions(x);modal('50 questions · '+(djBy(x.djId)?.name||x.title||'Invité'),`<div class="form-field"><label>Dossier de préparation à relire</label><textarea class="editor" id="questions-text">${safe(txt)}</textarea></div><div class="button-row">${button('⇩ Télécharger 50 questions','questions-txt','',`data-id="${safe(id)}"`)}${button('✉ Préparer un courriel','questions-mail','secondary',`data-id="${safe(id)}"`)}</div>`)}return}
if(a==='questions-txt'){let x=data.interviews.find(y=>y.id===id);if(x)download($('questions-text')?.value||makeQuestions(x),fileName('questions_'+(djBy(x.djId)?.name||'invite')));return}
if(a==='questions-mail'){let x=data.interviews.find(y=>y.id===id);if(x)createMail('Entrevue · '+(djBy(x.djId)?.name||x.title),'ANTBRO LIVE — 50 questions — '+(djBy(x.djId)?.name||x.title),$('questions-text')?.value||makeQuestions(x),'Entrevue');return}
if(a==='compose')return compose(id);if(a==='compose-selected')return compose($('mail-dj')?.value);
if(a==='copy-post'){const p=data.posts.find(x=>x.id===id);if(p)copyText(p.title+'\n\n'+p.body+'\n\nDestination : '+p.target+'\nValidation GRP : '+p.status);return}
if(a==='copy-group'){const g=data.groups.find(x=>x.id===id);if(g)copyText(g.name+'\nMission : '+g.mission+'\nRègles : '+g.rules+'\nLien : '+(g.link||'—'));return}
if(a==='backup')return backup();if(a==='backup-email'){backup();return backupEmail()}if(a==='import'){$('import-backup').click();return}if(a==='export-csv')return exportCSV();if(a==='print-report'){modal('Bilan global',`<h3>ANTBRO × GRP INTERNATIONAL — Bilan</h3><p>Artistes : ${data.djs.length} · Groupes : ${data.groups.length} · Entrevues : ${data.interviews.length} · Opportunités : ${data.bookings.length}.</p><p>Le document est fondé sur les éléments réellement enregistrés dans ce navigateur.</p><div class="button-row">${button('Imprimer / enregistrer en PDF','print-now','')}</div>`);return}if(a==='print-now')return window.print();
if(a==='share-backup')return shareBackup();if(a==='mail-share'){let m=data.mailHistory.find(x=>x.id===id);if(m){let txt=$('mail-body')?.value||m.body;return shareFile(fileName('dossier_'+m.title),txt,'text/plain;charset=utf-8',m.subject,'Dossier GRP International / Antbro à transmettre.')}return}
if(a==='mail-txt'){const m=data.mailHistory.find(x=>x.id===id);if(m){let txt=$('mail-body')?.value||m.body;download(txt,fileName('courriel_'+m.title));}return}
if(a==='mail-copy'){let m=data.mailHistory.find(x=>x.id===id);if(m)copyText($('mail-body')?.value||m.body);return}
if(a==='export-mail'){let m=data.mailHistory.find(x=>x.id===id);if(m)download(m.body,fileName('courriel_'+m.title));return}
if(a==='mark-mail'){let m=data.mailHistory.find(x=>x.id===id);if(m){m.sent=!m.sent;persist();render();toast(m.sent?'Envoi marqué comme déclaré (non vérifié).':'Replacé en brouillon.')}return}
if(a==='delete-record'){const lookup={dj:'djs',group:'groups',interview:'interviews',booking:'bookings',post:'posts',activity:'activities',task:'tasks'};let kind=el.dataset.kind,k=lookup[kind];if(k&&confirm('Supprimer définitivement cette fiche locale ? Cette action ne peut pas être annulée.')){data[k]=data[k].filter(x=>x.id!==id);persist();closeModal();render();toast('Fiche supprimée de cet appareil.')}return}
if(a==='reset'){if(confirm('EFFACER TOUTES les données locales ? Téléchargez une sauvegarde avant de continuer.'))if(confirm('Dernière confirmation : effacer toutes les fiches, historiques et réglages ?')){data=START();persist();navigate('dashboard');toast('Données locales effacées.')}return}}
function submitEntity(f){let type=f.dataset.entity,id=f.dataset.id;const map={dj:'djs',group:'groups',interview:'interviews',booking:'bookings',post:'posts',activity:'activities',task:'tasks'};let key=map[type];if(!key)return;let obj=id?data[key].find(x=>x.id===id):null;const prevPhoto=obj?.photo||'';const fd=new FormData(f),v=Object.fromEntries([...fd].filter(([k])=>k!=='status').map(([k,v])=>[k,typeof v==='string'?v.trim():v]));if(!obj){obj={id:uid(),date:day()};data[key].push(obj)}Object.assign(obj,v);if(fd.has('status'))obj.status=String(fd.get('status'));if(type==='dj'){obj.steps=Array.isArray(obj.steps)?obj.steps:[];if(!v.photo&&/^data:image\/(jpeg|png|webp);base64,/.test(prevPhoto))obj.photo=prevPhoto;let upload=$('photo-upload')?.files?.[0];if(upload){if(upload.size>5_000_000)return toast('Photo trop volumineuse (maximum 5 Mo).');const reader=new FileReader();reader.onload=()=>{let img=new Image();img.onload=()=>{let scale=Math.min(1,420/img.width,420/img.height);let can=document.createElement('canvas');can.width=Math.round(img.width*scale);can.height=Math.round(img.height*scale);can.getContext('2d').drawImage(img,0,0,can.width,can.height);obj.photo=can.toDataURL('image/jpeg',.72);persist();closeModal();render();toast('Dossier et portrait enregistrés.');};img.onerror=()=>toast('Image invalide.');img.src=reader.result;};reader.readAsDataURL(upload);return}}
if(type==='task')obj.done=fd.get('status')==='Terminée';if(type==='post'&&!obj.date)obj.date=day();if(type==='activity'&&!obj.date)obj.date=day();persist();closeModal();render();toast('Enregistré dans le bureau.');}
function sendMail(f){const id=f.dataset.id,m=data.mailHistory.find(x=>x.id===id);if(!m)return;let v=Object.fromEntries(new FormData(f)),to=(v.to||'').trim(),cc=(v.cc||'').trim(),subject=(v.subject||'').trim(),body=(v.body||'').trim();if(!to){toast('Ajoutez le destinataire principal dans les réglages ou le formulaire.');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)){toast('Adresse de destination invalide.');return}m.subject=subject;m.body=body;persist();let href='mailto:'+encodeURIComponent(to)+(cc?'?cc='+encodeURIComponent(cc)+'&':'?')+'subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);if(href.length>7500){toast('Dossier volumineux : téléchargez le TXT, puis joignez-le à un courriel.');download(body,fileName('dossier_'+m.title));return}window.location.href=href;toast('Messagerie ouverte si disponible. Vous devez cliquer sur Envoyer.');}
document.addEventListener('click',e=>{let nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return}let act=e.target.closest('[data-action]');if(act){e.preventDefault();handleAction(act);return}if(e.target.id==='modal-cover')closeModal()});
document.addEventListener('submit',e=>{if(e.target.id==='media-form'){e.preventDefault();return submitMedia(e.target)}if(e.target.id==='settings-form'){e.preventDefault();let fd=new FormData(e.target);for(const k of ['to','cc','signature'])data.settings[k]=String(fd.get(k)||'').trim();persist();toast('Destinataires sauvegardés sur cet appareil.');return}if(e.target.id==='entity-form'){e.preventDefault();submitEntity(e.target);return}if(e.target.id==='mail-form'){e.preventDefault();sendMail(e.target);return}});
document.addEventListener('input',e=>{if(e.target.id==='dj-search'){search=e.target.value;const found=data.djs.filter(d=>[d.name,d.genre,d.city,d.status].join(' ').toLowerCase().includes(search.toLowerCase()));let n=$('dj-cards');if(n)n.innerHTML=found.length?found.map(djTile).join(''):empty('Aucun résultat','Modifiez la recherche.');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('sidebar').classList.remove('open')}});
$('menu-button').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
$('top-search-button').addEventListener('click',()=>{navigate('djs');$('dj-search')?.focus()});
$('top-backup').addEventListener('click',backup);
$('top-settings').addEventListener('click',()=>navigate('settings'));
$('import-backup').addEventListener('change',e=>{const f=e.target.files?.[0];if(f)importJSON(f);e.target.value=''});
if(new URLSearchParams(location.search).has('monitor'))renderPublicMonitor();else render();
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
